function buildKey(prefix, namespace, key) {
  const parts = [prefix, namespace, key];
  for (const part of parts) {
    if (!/^[a-zA-Z0-9._-]+$/.test(part)) throw new Error(`Invalid key part: ${part}`);
  }
  return parts.join(":");
}

for (const [ns, key] of [["ada", "tasks.list"], ["ada", "x:tasks.list"], ["*", "tasks.list"]]) {
  try {
    console.log(buildKey("taskapi", ns, key));
  } catch (error) {
    console.log(error.message);
  }
}

